def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    container_patches = image_patch.find("container")
    if not container_patches:
        return image_patch

    container_patch = container_patches[0]
    vegetables = ["broccoli", "cauliflower", "cucumber", "carrots"]
    vegetable_patches = []

    for vegetable in vegetables:
        vegetable_patches.extend(image_patch.find(vegetable))

    if not vegetable_patches:
        return container_patch

    vegetable_depths = {v: vp.compute_depth() for v, vp in zip(vegetables, vegetable_patches)}
    vegetable_patches.sort(key=lambda vp: vegetable_depths[vp.best_text_match(vegetables)])

    return vegetable_patches[-1]

