    duck_patches = image_patch.find("duck")
    if len(duck_patches) < 3: 
        return image_patch

    # Sort ducks by their vertical center
    duck_patches.sort(key=lambda d: d.vertical_center)

    # Get the three highest ducks
    top_three_ducks = duck_patches[-3:]

    # Check if the first duck is higher than the other two
    if is_above(top_three_ducks[0], top_three_ducks[1]) and is_above(top_three_ducks[0], top_three_ducks[2]):
        return top_three_ducks[0]
    elif is_above(top_three_ducks[1], top_three_ducks[0]) and is_above(top_three_ducks[1], top_three_ducks[2]):
        return top_three_ducks[1]
    else:
        return top_three_ducks[2]

